'use client';

import { useEffect,useMemo,useRef,useState,type FormEvent } from 'react';
import { QueryClient,QueryClientProvider,useQuery,useQueryClient } from '@tanstack/react-query';
import { LayoutDashboard,Wallet,HandCoins,History,FileDown,Settings2,LogOut,RefreshCw,Plus,ChevronLeft,ChevronRight,Check,AlertCircle,ShieldCheck,Building2,CreditCard,Users,X,Download,ArrowRight,WifiOff,SlidersHorizontal,Pencil,Trash2,Search,Boxes,MoreHorizontal } from 'lucide-react';
import { Assets } from './components/assets/Assets';

type Person={id:string;login:string;name:string;role:'ADMIN'|'NV'|'KETOAN';houses:string[];accounts:string[]};
type House={code:string;name:string;note:string;active:boolean};
type Account={name:string;bank:string;active:boolean};
type Due={houseCode:string;room:string;month:string;due:number;paid:number;remaining:number};
type Receipt={id:string;month:string;houseCode:string;room:string;collector:string;payer:string;amount:number;method:string;accountName:string|null;receivedAt:string;transferAt:string;transferMemo:string;note:string;status:string;syncStatus:string;version:number};
type Meta={houses:House[];accounts:Account[];months:string[];dueLastRead:string|null};
type Dashboard={month:string;due:number;paid:number;remaining:number;cash:number;transfer:number;myCollected:number;roomsPaid:number;roomsPartial:number;roomsUnpaid:number;count:number;houses:{code:string;due:number;paid:number;remaining:number}[];accounts:{name:string;amount:number}[];daily:{day:string;amount:number}[]};
type Report={groups:{account:Account;count:number;total:number;receipts:Receipt[]}[];total:number;accountOptions:Account[]};
type StaffReport={employees:{id:string;name:string;login:string;role:string;cash:number;transfer:number;total:number;cashCount:number;transferCount:number;count:number}[];totals:{cash:number;transfer:number;total:number;count:number}};
type Sync={binding:string;collectionsEnabled:boolean;state:{key:string;value:string}[];outbox:{status:string;_count:number}[];conflicts:{id:string;entityType:string;entityId:string;reason:string;createdAt:string}[];catalog:{key:string;status:string;error:string|null}[]};

const money=(n:number)=>new Intl.NumberFormat('vi-VN').format(n)+' đ';
const errText=(error:unknown)=>error instanceof Error?error.message:String(error);
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const toApiDate=(date:string)=>date?`${date.slice(8,10)}/${date.slice(5,7)}/${date.slice(0,4)}`:'';
const toPicker=(date:string)=>/^\d{2}\/\d{2}\/\d{4}$/.test(date)?`${date.slice(6)}-${date.slice(3,5)}-${date.slice(0,2)}`:date;
async function api<T=any>(path:string,init?:RequestInit):Promise<T>{
  const r=await fetch('/api'+path,{credentials:'same-origin',cache:'no-store',...init,headers:{...(init?.body?{'Content-Type':'application/json'}:{}),...init?.headers}});
  if(!r.ok){const body=await r.json().catch(()=>({}));throw new Error(body.error||`Yêu cầu lỗi ${r.status}`);}
  return r.json();
}
const post=<T=any,>(path:string,value:unknown,method='POST')=>api<T>(path,{method,body:JSON.stringify(value)});
const parameters=(v:Record<string,string|number|undefined>)=>'?' + new URLSearchParams(Object.entries(v).filter(([,n])=>n!==undefined&&n!=='').map(([k,n])=>[k,String(n)])).toString();
const nav=[{id:'dashboard',title:'Tổng quan',Icon:LayoutDashboard},{id:'dues',title:'Hóa đơn',Icon:Wallet},{id:'collect',title:'Thu tiền',Icon:HandCoins},{id:'history',title:'Lịch sử',Icon:History},{id:'reports',title:'Báo cáo',Icon:FileDown},{id:'assets',title:'Tài sản',Icon:Boxes},{id:'admin',title:'Quản trị',Icon:Settings2}] as const;
type Tab=typeof nav[number]['id'];
type PayForm={id:string;month:string;houseCode:string;room:string;amount:string;method:'Tiền mặt'|'Chuyển khoản';accountName:string;note:string;transferAt:string;transferMemo:string;version?:number};
function freshPay(d:Due):PayForm{return {id:'VW-'+crypto.randomUUID(),month:d.month,houseCode:d.houseCode,room:d.room,amount:String(d.remaining),method:'Tiền mặt',accountName:'',note:'',transferAt:today(),transferMemo:''};}

function useCall<T>(key:unknown[],path:string,enabled=true){return useQuery<T>({queryKey:key,queryFn:()=>api<T>(path),enabled,staleTime:25000,refetchOnWindowFocus:true});}
function Badge({value}:{value:string}){const normal=value==='SYNCED'||value==='ACTIVE';const bad=value==='FAILED'||value==='CONFLICT'||value==='DELETED';return <span className={'badge '+(normal?'badge-ok':bad?'badge-danger':'badge-wait')}>{({SYNCED:'Đã đồng bộ',PENDING:'Chờ đồng bộ',FAILED:'Đồng bộ lỗi',CONFLICT:'Xung đột',ACTIVE:'Đang dùng',DELETED:'Đã hủy'} as Record<string,string>)[value]||value}</span>}
function Blank({message}:{message:string}){return <div className="blank">{message}</div>}
function Spinner(){return <div className="skeleton" aria-label="Đang tải dữ liệu"><span/><span/><span/></div>}

function Vincent(){
  const qc=useQueryClient();
  const actionLock=useRef(false);
  const [user,setUser]=useState<Person|null>(null),[ready,setReady]=useState(false),[enabled,setEnabled]=useState(false);
  const [login,setLogin]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
  const [tab,setTab]=useState<Tab>('dashboard'),[month,setMonth]=useState(()=>today().slice(0,7)),[page,setPage]=useState(1),[duesPage,setDuesPage]=useState(1),[search,setSearch]=useState(''),[filterHouse,setFilterHouse]=useState('');
  const [mobileMoreOpen,setMobileMoreOpen]=useState(false);
  const [reportView,setReportView]=useState<'staff'|'transfers'>('staff'),[reportFilterOpen,setReportFilterOpen]=useState(false);
  const [pay,setPay]=useState<PayForm|null>(null),[editing,setEditing]=useState(false),[cancel,setCancel]=useState<Receipt|null>(null),[confirm,setConfirm]=useState(false),[allowDuplicate,setAllowDuplicate]=useState(false);
  const [reportAccounts,setReportAccounts]=useState<string[]>([]),[reportAccountSearch,setReportAccountSearch]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[reportStatus,setReportStatus]=useState<'ACTIVE'|'DELETED'>('ACTIVE');
  const [staffFrom,setStaffFrom]=useState(''),[staffTo,setStaffTo]=useState('');
  const [staffReportSort,setStaffReportSort]=useState<'revenue-desc'|'revenue-asc'|'name'>('revenue-desc');
  const [adminTab,setAdminTab]=useState<'houses'|'accounts'|'users'|'sync'>('houses'),[adminFormOpen,setAdminFormOpen]=useState(false);
  const [adminHouseSearch,setAdminHouseSearch]=useState(''),[adminStaffSearch,setAdminStaffSearch]=useState('');
  const [houseForm,setHouseForm]=useState<House>({code:'',name:'',note:'',active:true}),[accountForm,setAccountForm]=useState<Account>({name:'',bank:'',active:true});
  const [staffForm,setStaffForm]=useState({id:'',login:'',name:'',password:'',role:'NV' as 'NV'|'ADMIN'|'KETOAN',active:true,houses:[] as string[],accounts:[] as string[]});
  const admin=user?.role==='ADMIN';
  const canCollect=!!user&&user.role!=='KETOAN'&&enabled;

  useEffect(()=>{api<{user:Person;collectionsEnabled:boolean}>('/auth/me').then(r=>{setUser(r.user);setEnabled(r.collectionsEnabled)}).catch(()=>{}).finally(()=>setReady(true));
    if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
  },[]);
  useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),4000);return ()=>clearTimeout(t);},[notice]);
  const meta=useQuery<Meta>({
    queryKey:['meta',user?.id],
    queryFn:()=>api<Meta>('/metadata'),
    enabled:!!user,
    staleTime:10000,
    refetchInterval:30000,
    refetchOnWindowFocus:true,
  });
  useEffect(()=>{
    if(!meta.data?.dueLastRead)return;
    void Promise.all([
      qc.invalidateQueries({queryKey:['dash']}),
      qc.invalidateQueries({queryKey:['dues']}),
      qc.invalidateQueries({queryKey:['admin-houses']}),
      qc.invalidateQueries({queryKey:['admin-sync']}),
    ]);
  },[meta.data?.dueLastRead,qc]);
  const dash=useCall<Dashboard>(['dash',user?.id,month],'/dashboard'+parameters({month}),!!user&&!!month&&tab==='dashboard');
  const dues=useCall<{total:number;items:Due[];page:number;summary?:{total:number;roomsPaid:number;roomsIncomplete:number}}>(['dues',user?.id,month,duesPage,filterHouse,search,tab==='collect'],'/dues'+parameters({month,page:duesPage,house:filterHouse,search,summary:tab==='collect'?'true':undefined}),!!user&&!!month&&(tab==='dues'||tab==='collect'));
  const availableMonths=[...new Set([today().slice(0,7),month,...(meta.data?.months||[])])].filter(Boolean).sort().reverse();
  const history=useCall<{total:number;items:Receipt[];size:number}>(['history',user?.id,month,page,search,filterHouse],'/receipts'+parameters({month,page,search,house:filterHouse}),!!user&&!!month&&tab==='history');
  const repParams={month,from:toApiDate(from),to:toApiDate(to),accountNames:reportAccounts.join(','),status:reportStatus};
  const reports=useCall<Report>(['reports',user?.id,repParams],'/reports/transfers'+parameters(repParams),!!user&&!!month&&tab==='reports');
  const staffReports=useCall<StaffReport>(['reports','staff',user?.id,month,staffFrom,staffTo],'/reports/staff'+parameters({month,from:toApiDate(staffFrom),to:toApiDate(staffTo)}),!!user&&!!month&&tab==='reports');
  const sortedStaffReports=useMemo(()=>{
    const rows=[...(staffReports.data?.employees||[])];
    if(staffReportSort==='name')return rows.sort((a,b)=>a.name.localeCompare(b.name,'vi'));
    return rows.sort((a,b)=>staffReportSort==='revenue-asc'?a.total-b.total:b.total-a.total);
  },[staffReports.data?.employees,staffReportSort]);
  const staffChartRows=useMemo(()=>sortedStaffReports.filter(row=>row.total>0),[sortedStaffReports]);
  const reportAccountOptions=useMemo(()=>{
    const options=reports.data?.accountOptions?.length?reports.data.accountOptions:(meta.data?.accounts||[]);
    const term=reportAccountSearch.trim().toLocaleLowerCase('vi');
    return term?options.filter(a=>(a.name+' '+(a.bank||'')).toLocaleLowerCase('vi').includes(term)):options;
  },[reports.data?.accountOptions,meta.data?.accounts,reportAccountSearch]);
  const reportTransactionCount=reports.data?.groups.reduce((total,g)=>total+g.count,0)||0;
  const houses=useCall<House[]>(['admin-houses'],'/admin/houses',!!admin&&tab==='admin'&&adminTab==='houses');
  const accounts=useCall<Account[]>(['admin-accounts'],'/admin/accounts',!!admin&&tab==='admin'&&adminTab==='accounts');
  const staff=useCall<(Person&{active:boolean;hasPassword:boolean})[]>(['admin-staff'],'/admin/users',!!admin&&tab==='admin'&&adminTab==='users');
  const sync=useCall<Sync>(['admin-sync'],'/admin/sync',!!admin&&tab==='admin'&&adminTab==='sync');
  const filteredAdminHouses=useMemo(()=>{const term=adminHouseSearch.trim().toLocaleLowerCase('vi');return term?(houses.data||[]).filter(h=>(h.code+' '+h.name+' '+h.note).toLocaleLowerCase('vi').includes(term)):(houses.data||[]);},[houses.data,adminHouseSearch]);
  const filteredAdminStaff=useMemo(()=>{const term=adminStaffSearch.trim().toLocaleLowerCase('vi');return term?(staff.data||[]).filter(u=>(u.name+' '+u.login+' '+u.role+' '+u.houses.join(' ')).toLocaleLowerCase('vi').includes(term)):(staff.data||[]);},[staff.data,adminStaffSearch]);
  const houseLabel=(code:string)=>meta.data?.houses.find(h=>h.code===code)?.name||'Tòa nhà '+code;
  const pending=busy;
  function changed(){void Promise.all([qc.invalidateQueries({queryKey:['dash']}),qc.invalidateQueries({queryKey:['dues']}),qc.invalidateQueries({queryKey:['history']}),qc.invalidateQueries({queryKey:['reports']}),qc.invalidateQueries({queryKey:['meta']}),...['admin-houses','admin-accounts','admin-staff','admin-sync'].map(k=>qc.invalidateQueries({queryKey:[k]}))]);}
  async function doAction<T>(run:()=>Promise<T>,text:string){if(actionLock.current)return null;actionLock.current=true;setBusy(true);setError('');try{const r=await run();changed();setNotice(text);return r;}catch(e){setError(errText(e));return null;}finally{actionLock.current=false;setBusy(false)}}
  async function onLogin(e:FormEvent){e.preventDefault();const r=await doAction(()=>post<{user:Person;collectionsEnabled:boolean}>('/auth/login',{login,password}),'Đăng nhập thành công');if(r){setMonth(today().slice(0,7));setUser(r.user);setEnabled(r.collectionsEnabled);setPassword('');}}
  async function logout(){setMobileMoreOpen(false);await api('/auth/logout',{method:'POST'}).catch(()=>{});setUser(null);qc.clear();setTab('dashboard');}
  function navTo(next:Tab){setMobileMoreOpen(false);setTab(next);setSearch('');setPage(1);setDuesPage(1);setError('');}
  async function savePay(){if(!pay)return;
    if(!confirm){setConfirm(true);return;}
    const data={...pay,amount:pay.amount,transferAt:pay.method==='Chuyển khoản'?toApiDate(pay.transferAt):null,accountName:pay.method==='Chuyển khoản'?pay.accountName:null,
      transferMemo:pay.method==='Chuyển khoản'?pay.transferMemo:'',allowDuplicate};
    const r=await doAction(()=>editing?post('/receipts/'+pay.id,data,'PATCH'):post('/receipts',data),editing?'Đã lưu sửa đổi. Đang chờ đồng bộ.':'Đã ghi nhận thu. Đang chờ đồng bộ.');
    if(r){setPay(null);setConfirm(false);setEditing(false);setAllowDuplicate(false);}
  }
  function openEdit(r:Receipt){setPay({id:r.id,month:r.month,houseCode:r.houseCode,room:r.room,amount:String(r.amount),method:r.method as PayForm['method'],accountName:r.accountName||'',note:r.note,transferAt:toPicker(r.transferAt)||today(),transferMemo:r.transferMemo,version:r.version});setEditing(true);setConfirm(false);}
  async function removeReceipt(){if(!cancel)return;const r=await doAction(()=>post('/receipts/'+cancel.id,{version:cancel.version},'DELETE'),'Đã hủy giao dịch. Đang chờ đồng bộ.');if(r)setCancel(null);}
  async function download(mode:'pdf'|'zip'){
    setBusy(true);setError('');try{
      const r=await fetch('/api/reports/transfers'+parameters({...repParams,format:mode}),{credentials:'same-origin',cache:'no-store'});
      if(!r.ok)throw new Error((await r.json()).error||'Không thể xuất báo cáo');
      const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=`vincent-chuyen-khoan.${mode}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
    }catch(e){setError(errText(e));}finally{setBusy(false);}
  }
  async function saveHouse(e:FormEvent){e.preventDefault();const r=await doAction(()=>post('/admin/houses',houseForm),'Đã lưu tòa nhà');if(r){setHouseForm({code:'',name:'',note:'',active:true});setAdminFormOpen(false);void qc.invalidateQueries({queryKey:['admin-houses']});void qc.invalidateQueries({queryKey:['meta']});}}
  async function saveAccount(e:FormEvent){e.preventDefault();const r=await doAction(()=>post('/admin/accounts',{name:accountForm.name,bank:accountForm.bank}),'Đã lưu tài khoản nhận');if(r){setAccountForm({name:'',bank:'',active:true});setAdminFormOpen(false);void qc.invalidateQueries({queryKey:['admin-accounts']});void qc.invalidateQueries({queryKey:['meta']});}}
  async function deleteHouse(){if(!houseForm.code)return;const r=await doAction(()=>post('/admin/houses/'+encodeURIComponent(houseForm.code),{},'DELETE'),'Đã xóa tòa nhà');if(r){setHouseForm({code:'',name:'',note:'',active:true});setAdminFormOpen(false);void qc.invalidateQueries({queryKey:['admin-houses']});void qc.invalidateQueries({queryKey:['meta']});}}
  async function deleteAccount(){if(!accountForm.name)return;const r=await doAction(()=>post('/admin/accounts/'+encodeURIComponent(accountForm.name),{},'DELETE'),'Đã xóa tài khoản nhận');if(r){setAccountForm({name:'',bank:'',active:true});setAdminFormOpen(false);void qc.invalidateQueries({queryKey:['admin-accounts']});void qc.invalidateQueries({queryKey:['meta']});}}
  async function saveStaff(e:FormEvent){e.preventDefault();const {id,...v}=staffForm;const r=await doAction(()=>id?post('/admin/users/'+id,{...v,password:v.password||undefined},'PATCH'):post('/admin/users',v), 'Đã lưu tài khoản nhân viên');if(r){setStaffForm({id:'',login:'',name:'',password:'',role:'NV',active:true,houses:[],accounts:[]});setAdminFormOpen(false);void qc.invalidateQueries({queryKey:['admin-staff']});}}
  async function deleteStaff(){if(!staffForm.id)return;const r=await doAction(()=>post('/admin/users/'+staffForm.id,{},'DELETE'),'Đã xóa nhân viên khỏi quản trị');if(r){setStaffForm({id:'',login:'',name:'',password:'',role:'NV',active:true,houses:[],accounts:[]});setAdminFormOpen(false);void qc.invalidateQueries({queryKey:['admin-staff']});}}

  if(!ready)return <div className="preload"><Spinner/></div>;
  if(!user)return <div className="auth-stage"><div className="auth-mark"><span className="brand-symbol">V</span><span>VINCENT <small>SERVER EDITION</small></span></div><div className="auth-card"><div className="auth-head"><span className="eyebrow">Quản lý vận hành</span><h1>Chào mừng trở lại</h1><p>Đăng nhập để quản lý thu tiền, công nợ và báo cáo theo tòa nhà.</p></div><form onSubmit={onLogin}><label>Số điện thoại<input autoComplete="username" inputMode="tel" required value={login} onChange={e=>setLogin(e.target.value)} placeholder="Nhập số điện thoại" /></label><label>Mật khẩu<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Nhập mật khẩu"/></label>{error&&<p className="error-box">{error}</p>}<button className="primary full" disabled={pending}>Đăng nhập <ArrowRight size={18}/></button></form></div><p className="auth-foot">VINCENT · Hệ thống thu tiền nội bộ</p></div>;

  return <div className="app-frame">
    <aside className="sidebar"><div className="brand"><span className="brand-symbol">V</span><span>VINCENT <small>SERVER EDITION</small></span></div><div className="menu-caption">Không gian làm việc</div><nav className="side-menu">{nav.filter(n=>n.id!=='admin'||admin).map(n=><button key={n.id} onClick={()=>navTo(n.id)} className={'nav-item '+(tab===n.id?'selected':'')}><n.Icon size={19} strokeWidth={1.8}/><span>{n.title}</span>{tab===n.id&&<span className="nav-active-dot"/>}</button>)}</nav><div className="side-foot"><div className="person-avatar">{user.name.slice(0,1).toUpperCase()}</div><div className="person-info"><strong>{user.name}</strong><small>{admin?'Quản trị viên':user.role==='KETOAN'?'Nhân viên kế toán':'Nhân viên thu tiền'}</small></div><button title="Đăng xuất" className="icon-btn" onClick={logout}><LogOut size={18}/></button></div></aside>
    <div className="workspace"><header className="topline"><div className="mobile-brand"><span className="brand-symbol">V</span> VINCENT</div><div className="breadcrumb">Không gian làm việc <span>/</span> <strong>{nav.find(n=>n.id===tab)?.title}</strong></div><div className="top-actions"><span className={'live-flag '+(enabled?'':'readonly')}><span/> {enabled?'Đang ghi nhận thu':'Chế độ chỉ xem'}</span><button className="icon-btn" aria-label="Tải lại dữ liệu" onClick={()=>{changed();setNotice('Đã làm mới dữ liệu lưu trên máy chủ.')}}><RefreshCw size={18}/></button></div></header>
    <main className="content"><div className="page-head"><div><h1>{nav.find(n=>n.id===tab)?.title}</h1><p>{({dashboard:'Theo dõi tình hình thu tiền và công nợ toàn bộ kỳ.',dues:'Theo dõi hóa đơn và số còn phải thu theo từng phòng.',collect:'Ghi nhận thanh toán cho phòng theo đúng kỳ thu.',history:'Tra cứu và kiểm soát từng giao dịch đã ghi nhận.',reports:'Theo dõi doanh thu theo nhân viên và đối soát tiền chuyển khoản.',assets:'Quản lý tài sản, kho vật tư, thiết bị cho thuê và bảo trì.',admin:'Cấu hình vận hành và kiểm soát đồng bộ.'} as Record<Tab,string>)[tab]}</p></div>{tab!=='admin'&&tab!=='assets'&&<div className="period"><label htmlFor="period">Kỳ thu</label><select id="period" value={month} onChange={e=>{setMonth(e.target.value);setPage(1);setDuesPage(1)}}>{availableMonths.map(m=><option key={m} value={m}>{m.slice(5)}/{m.slice(0,4)}</option>)}</select></div>}</div>
    {error&&<div role="alert" className="error-box dismiss"><AlertCircle size={17}/><span>{error}</span><button onClick={()=>setError('')} aria-label="Đóng"><X size={17}/></button></div>}
    {notice&&<div role="status" className="toast"><Check size={17}/>{notice}</div>}

    {tab==='dashboard'&&(dash.isLoading?<Spinner/>:dash.data?<><div className="metric-row"><div className="metric featured"><div className="metric-label">Tổng phải thu</div><strong>{money(dash.data.due)}</strong><small>Doanh thu tháng {Number(today().slice(5,7))}</small></div><div className="metric"><div className="metric-label">Đã thu</div><strong>{money(dash.data.paid)}</strong><small>{dash.data.due?Math.round(dash.data.paid/dash.data.due*100):0}% số tiền cần thu</small></div><div className="metric"><div className="metric-label">Còn phải thu</div><strong>{money(dash.data.remaining)}</strong><small>{dash.data.roomsPartial+dash.data.roomsUnpaid} phòng còn công nợ</small></div><div className="metric"><div className="metric-label">Tiền chuyển khoản</div><strong>{money(dash.data.transfer)}</strong><small>Tiền mặt: {money(dash.data.cash)}</small></div></div><div className="grid-main"><section className="surface"><div className="section-title"><h2>Tiến độ theo tòa nhà</h2><span>{dash.data.houses.length} tòa nhà</span></div>{dash.data.houses.length?dash.data.houses.map(h=><div className="progress-row" key={h.code}><div className="row-spread"><strong>{houseLabel(h.code)}</strong><span>{money(h.paid)} <b>/</b> {money(h.due)}</span></div><div className="progress-track"><div style={{width:`${h.due?Math.min(100,h.paid/h.due*100):0}%`}} /></div></div>):<Blank message="Chưa có dữ liệu cần thu cho kỳ này"/>}</section><section className="surface"><div className="section-title"><h2>Tình trạng thanh toán</h2><span>Theo phòng</span></div><div className="status-ring"><div className="ring-stat"><strong>{dash.data.roomsPaid+dash.data.roomsPartial+dash.data.roomsUnpaid}</strong><span>Phòng</span></div></div><div className="split-stat"><span><i className="dot green"/>Đã đủ</span><strong>{dash.data.roomsPaid}</strong></div><div className="split-stat"><span><i className="dot blue"/>Đã thu một phần</span><strong>{dash.data.roomsPartial}</strong></div><div className="split-stat"><span><i className="dot gray"/>Chưa thu</span><strong>{dash.data.roomsUnpaid}</strong></div></section></div><section className="surface"><div className="section-title"><h2>Tổng hợp theo tài khoản nhận</h2><span>Trong kỳ {month}</span></div><div className="account-grid">{dash.data.accounts.length?dash.data.accounts.map(a=><div key={a.name} className="account-tile"><CreditCard size={17}/><span>{a.name}</span><strong>{money(a.amount)}</strong></div>):<Blank message="Chưa phát sinh giao dịch chuyển khoản"/>}</div></section></>:<Blank message="Chưa có kỳ thu. Kiểm tra đồng bộ Google Sheets trong quản trị."/>) }

    {tab==='dues'&&<section className="surface"><div className="section-title"><h2>Danh sách hóa đơn theo phòng</h2><span>{dues.data?.total||0} phòng</span></div><div className="filters"><div className="search-wrap"><SlidersHorizontal size={16}/><input value={search} onChange={e=>{setSearch(e.target.value);setDuesPage(1)}} placeholder="Tìm phòng hoặc tòa nhà"/></div><select value={filterHouse} onChange={e=>{setFilterHouse(e.target.value);setDuesPage(1)}}><option value="">Tất cả tòa nhà</option>{meta.data?.houses.map(h=><option value={h.code} key={h.code}>{houseLabel(h.code)}</option>)}</select></div>{dues.isLoading?<Spinner/>:dues.data?.items.length?<><div className="table-scroll"><table><thead><tr><th>Tòa nhà / Phòng</th><th>Phải thu</th><th>Đã thu</th><th>Còn lại</th><th>Trạng thái</th></tr></thead><tbody>{dues.data.items.map(d=><tr key={d.houseCode+'|'+d.room}><td><strong>{houseLabel(d.houseCode)}</strong><small className="subline">Phòng {d.room}</small></td><td>{money(d.due)}</td><td>{money(d.paid)}</td><td className="emphasis">{money(d.remaining)}</td><td><span className={'badge '+(d.remaining===0?'badge-ok':d.paid>0?'badge-wait':'')}>{d.remaining===0?'Đã đủ':d.paid?'Thu một phần':'Chưa thu'}</span></td></tr>)}</tbody></table></div><Pager total={dues.data.total} page={duesPage} size={100} move={setDuesPage}/></>:<Blank message="Không có hóa đơn phù hợp. Hãy kiểm tra kỳ thu và bộ lọc."/>}</section>}

    {tab==='collect'&&<section className="surface collect-surface">
      <div className="section-title">
        <div><h2>Ghi nhận thu tiền</h2><p className="muted-text">Chọn phòng để ghi nhận thanh toán theo kỳ thu.</p></div>
        <span>{dues.data?.total||0} phòng phù hợp</span>
      </div>
      <div className="collection-stats" aria-label="Tổng hợp trạng thái thu tiền">
        <div className="collection-stat"><span>Tổng phòng</span><strong>{dues.data?.summary?.total??'—'}</strong></div>
        <div className="collection-stat success"><span>Đã thu đủ</span><strong>{dues.data?.summary?.roomsPaid??'—'}</strong></div>
        <div className="collection-stat outstanding"><span>Chưa hoàn tất</span><strong>{dues.data?.summary?.roomsIncomplete??'—'}</strong></div>
      </div>
      <div className="filters">
        <div className="search-wrap"><HandCoins size={16}/><input value={search} onChange={e=>{setSearch(e.target.value);setDuesPage(1)}} placeholder="Tìm nhanh phòng hoặc tòa nhà"/></div>
        <select value={filterHouse} onChange={e=>{setFilterHouse(e.target.value);setDuesPage(1)}}><option value="">Tất cả tòa nhà</option>{meta.data?.houses.map(h=><option value={h.code} key={h.code}>{houseLabel(h.code)}</option>)}</select>
      </div>
      {!canCollect&&<div className="readonly-note"><ShieldCheck size={18}/><span>{user.role==='KETOAN'?'Tài khoản kế toán chỉ được xem và đối soát dữ liệu.':'Hệ thống đang ở chế độ chỉ xem.'}</span></div>}
      {dues.isLoading?<Spinner/>:dues.data?.items.length?<><div className="collection-grid">
        {dues.data.items.map(d=><article className={'collection-card '+(d.remaining===0?'settled':'')} key={d.houseCode+'|'+d.room}>
          <div className="collection-room"><span className="collection-house">{houseLabel(d.houseCode)}</span><strong>Phòng {d.room}</strong><span className={'collection-status '+(d.remaining===0?'complete':d.paid>0?'partial':'unpaid')}>{d.remaining===0?'Đã thu đủ':d.paid>0?'Thu một phần':'Chưa thu'}</span></div>
          <div className="collection-money">
            <div className="collection-line"><span>Phải thu</span><b>{money(d.due)}</b></div>
            <div className="collection-line"><span>Đã thu</span><b>{money(d.paid)}</b></div>
            <div className="collection-remaining"><small>Còn thiếu</small><strong>{money(d.remaining)}</strong></div>
          </div>
          {d.remaining>0?<button className="primary collect-btn" disabled={!canCollect} onClick={()=>{setPay(freshPay(d));setConfirm(false);setEditing(false);setAllowDuplicate(false)}}><HandCoins size={17}/> Thu tiền</button>:<span className="collection-done"><Check size={15}/> Đã hoàn tất</span>}
        </article>)}
      </div><Pager total={dues.data.total} page={duesPage} size={100} move={setDuesPage}/></>:<Blank message="Không có phòng phù hợp trong kỳ thu này"/>}
    </section>}

    {tab==='history'&&<section className="surface"><div className="section-title"><h2>Lịch sử giao dịch</h2><span>{history.data?.total||0} giao dịch</span></div><div className="filters"><div className="search-wrap"><History size={16}/><input placeholder="Tìm phòng, nội dung chuyển khoản, mã giao dịch..." value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}}/></div><select value={filterHouse} onChange={e=>{setFilterHouse(e.target.value);setPage(1)}}><option value="">Tất cả tòa nhà</option>{meta.data?.houses.map(h=><option key={h.code} value={h.code}>{houseLabel(h.code)}</option>)}</select></div>{history.isLoading?<Spinner/>:history.data?.items.length?<><div className="table-scroll"><table><thead><tr><th>Ngày thu</th><th>Nhà / Phòng</th><th>Hình thức</th><th>Số tiền</th><th>Đồng bộ</th><th aria-label="Thao tác"/></tr></thead><tbody>{history.data.items.map(r=><tr key={r.id}><td>{r.receivedAt}<small className="subline">{r.id.slice(0,12)}…</small></td><td><strong>{r.houseCode} · {r.room}</strong><small className="subline">{r.collector}</small></td><td>{r.method}<small className="subline">{r.accountName||''}</small></td><td className="emphasis">{money(r.amount)}</td><td><Badge value={r.syncStatus}/></td><td>{canCollect&&<div className="icon-actions"><button className="row-icon" title="Sửa giao dịch" aria-label="Sửa giao dịch" onClick={()=>openEdit(r)}><Pencil size={16}/></button><button className="row-icon danger" title="Xóa giao dịch" aria-label="Xóa giao dịch" onClick={()=>setCancel(r)}><Trash2 size={16}/></button></div>}</td></tr>)}</tbody></table></div><Pager total={history.data.total} page={page} size={history.data.size} move={setPage}/></>:<Blank message="Chưa có giao dịch trong kỳ này"/>}</section>}

    {tab==='reports'&&<>
      <section className="report-top" aria-label="Tổng hợp doanh thu">
        <div className="report-top-heading"><div><p className="eyebrow">Báo cáo doanh thu</p><h2>Tháng {Number(month.slice(5))}/{month.slice(0,4)}</h2></div><span>{staffReports.data?.totals.count||0} giao dịch</span></div>
        <div className="report-summary-grid">
          <div className="report-summary-card featured"><small>Tổng đã thu</small><strong>{staffReports.data?money(staffReports.data.totals.total):'—'}</strong><span>Doanh thu trong kỳ</span></div>
          <div className="report-summary-card"><small>Tiền mặt</small><strong>{staffReports.data?money(staffReports.data.totals.cash):'—'}</strong><span>Đã ghi nhận</span></div>
          <div className="report-summary-card"><small>Chuyển khoản</small><strong>{staffReports.data?money(staffReports.data.totals.transfer):'—'}</strong><span>Đã ghi nhận</span></div>
          <div className="report-summary-card"><small>Giao dịch</small><strong>{staffReports.data?.totals.count??'—'}</strong><span>Toàn bộ nhân viên</span></div>
        </div>
      </section>
      <div className="report-view-tabs" role="tablist" aria-label="Chế độ báo cáo">
        <button type="button" role="tab" aria-selected={reportView==='staff'} className={reportView==='staff'?'active':''} onClick={()=>{setReportView('staff');setReportFilterOpen(false)}}><Users size={17}/> Nhân viên</button>
        <button type="button" role="tab" aria-selected={reportView==='transfers'} className={reportView==='transfers'?'active':''} onClick={()=>{setReportView('transfers');setReportFilterOpen(false)}}><CreditCard size={17}/> Chuyển khoản</button>
      </div>
      {reportView==='staff'&&<>
      <section className="surface report-staff">
        <div className="section-title"><div><p className="eyebrow">Doanh thu theo nhân viên</p><h2>Tổng hợp tiền đã thu</h2></div><span>{staffReports.data?.totals.count||0} giao dịch</span></div>
        <button className="secondary report-filter-trigger" type="button" onClick={()=>setReportFilterOpen(true)}><SlidersHorizontal size={17}/> Bộ lọc</button>
        {reportFilterOpen&&<button className="report-filter-backdrop" aria-label="Đóng bộ lọc" onClick={()=>setReportFilterOpen(false)}/>}
        <div className={'report-filter-sheet '+(reportFilterOpen?'open':'')}>
          <div className="report-filter-sheet-head"><strong>Bộ lọc nhân viên</strong><button className="icon-btn" aria-label="Đóng bộ lọc" onClick={()=>setReportFilterOpen(false)}><X size={19}/></button></div>
        <div className="report-staff-toolbar"><div><strong>Lọc và sắp xếp</strong><small>Dùng ngày ghi nhận thu tiền, độc lập với ngày chuyển khoản.</small></div><div className="report-staff-controls"><label>Sắp xếp<select value={staffReportSort} onChange={e=>setStaffReportSort(e.target.value as typeof staffReportSort)}><option value="revenue-desc">Doanh thu cao → thấp</option><option value="revenue-asc">Doanh thu thấp → cao</option><option value="name">Tên nhân viên A → Z</option></select></label><label>Từ ngày<input type="date" value={staffFrom} onChange={e=>setStaffFrom(e.target.value)}/></label><label>Đến ngày<input type="date" value={staffTo} onChange={e=>setStaffTo(e.target.value)}/></label></div></div>
          <button type="button" className="primary report-filter-apply" onClick={()=>setReportFilterOpen(false)}>Áp dụng bộ lọc</button>
        </div>
        {staffReports.isLoading?<Spinner/>:staffReports.error?<p className="error-box">{errText(staffReports.error)}</p>:sortedStaffReports.length?<><div className="staff-mix-chart"><div className="staff-mix-head"><div><strong>Tỷ lệ hình thức thanh toán</strong><small>Tiền mặt và chuyển khoản theo từng nhân viên có phát sinh doanh thu.</small></div><div className="staff-mix-legend"><span><i className="cash"/> Tiền mặt</span><span><i className="transfer"/> Chuyển khoản</span></div></div>{staffChartRows.length?staffChartRows.map(row=>{const cashPct=row.total?Math.round(row.cash/row.total*100):0;const transferPct=100-cashPct;return <div className="staff-mix-row" key={row.id}><div className="staff-mix-label"><strong>{row.name}</strong><small>{money(row.total)}</small></div><div className="staff-mix-track" title={`Tiền mặt ${cashPct}% · Chuyển khoản ${transferPct}%`}><span className="cash" style={{width:`${cashPct}%`}}/><span className="transfer" style={{width:`${transferPct}%`}}/></div><div className="staff-mix-values"><span>{cashPct}%</span><span>{transferPct}%</span></div></div>}):<Blank message="Chưa có doanh thu để hiển thị biểu đồ"/>}</div><div className="table-scroll mobile-card-table"><table className="staff-report-table"><thead><tr><th>Nhân viên</th><th>Vai trò</th><th>Tiền mặt</th><th>Chuyển khoản</th><th>Tổng thu</th><th>Giao dịch</th></tr></thead><tbody>{sortedStaffReports.map(row=><tr key={row.id}><td><strong>{row.name}</strong><small className="subline">{row.login||'Dữ liệu lịch sử'}</small></td><td>{row.role==='ADMIN'?'Quản trị':row.role==='KETOAN'?'Kế toán':row.role==='NV'?'Thu tiền':'Lịch sử'}</td><td>{money(row.cash)}<small className="subline">{row.cashCount} giao dịch</small></td><td>{money(row.transfer)}<small className="subline">{row.transferCount} giao dịch</small></td><td className="emphasis">{money(row.total)}</td><td>{row.count}</td></tr>)}</tbody></table></div></>:<Blank message="Chưa có dữ liệu thu theo nhân viên trong kỳ này"/>}
      </section>
      </>}
      {reportView==='transfers'&&<>
      <section className="surface report-panel">
        <div className="report-intro">
          <div><p className="eyebrow">Đối soát chuyển khoản</p><h2>Báo cáo thu qua tài khoản</h2><p>Lọc theo ngày chuyển, tài khoản nhận và trạng thái giao dịch trước khi xem chi tiết hoặc xuất file.</p></div>
          <p className="report-filtered-total">{reportTransactionCount} giao dịch · {reports.data?money(reports.data.total):'—'}</p>
        </div>
        <button type="button" className="secondary report-filter-trigger" onClick={()=>setReportFilterOpen(true)}><SlidersHorizontal size={17}/> Bộ lọc {reportAccounts.length>0?`(${reportAccounts.length} tài khoản)`:''}</button>
        {reportFilterOpen&&<button className="report-filter-backdrop" aria-label="Đóng bộ lọc" onClick={()=>setReportFilterOpen(false)}/>}
        <div className={'report-filter-sheet '+(reportFilterOpen?'open':'')}>
          <div className="report-filter-sheet-head"><strong>Bộ lọc chuyển khoản</strong><button className="icon-btn" aria-label="Đóng bộ lọc" onClick={()=>setReportFilterOpen(false)}><X size={19}/></button></div>
        <div className="report-filters">
          <label>Ngày chuyển từ<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label>
          <label>Đến ngày<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label>
          <label>Trạng thái<select value={reportStatus} onChange={e=>setReportStatus(e.target.value as typeof reportStatus)}><option value="ACTIVE">Đang hoạt động</option><option value="DELETED">Đã hủy (đối soát)</option></select></label>
        </div>
        <div className="report-account-filter">
          <div className="report-account-head">
            <div><strong>Tài khoản nhận</strong><small>{reportAccounts.length?`Đã chọn ${reportAccounts.length} tài khoản`:'Chưa chọn riêng — đang xem tất cả tài khoản'}</small></div>
            <div className="report-account-actions"><button type="button" className="link-btn" disabled={!reportAccountOptions.length} onClick={()=>setReportAccounts([...new Set([...reportAccounts,...reportAccountOptions.map(a=>a.name)])])}>Chọn tất cả hiển thị</button><button type="button" className="link-btn" disabled={!reportAccounts.length} onClick={()=>setReportAccounts([])}>Bỏ chọn</button></div>
          </div>
          <div className="report-account-search"><Search size={16}/><input aria-label="Tìm tài khoản nhận" placeholder="Tìm theo tên tài khoản hoặc ngân hàng" value={reportAccountSearch} onChange={e=>setReportAccountSearch(e.target.value)}/></div>
          <div className="checkbox-row report-accounts">{reportAccountOptions.length?reportAccountOptions.map(a=><label className={'check-pill '+(reportAccounts.includes(a.name)?'selected':'')} key={a.name}><input type="checkbox" checked={reportAccounts.includes(a.name)} onChange={e=>setReportAccounts(e.target.checked?[...new Set([...reportAccounts,a.name])]:reportAccounts.filter(x=>x!==a.name))}/><span><strong>{a.name}</strong><small>{a.bank||'Tài khoản lịch sử'}</small></span></label>):<span className="report-account-empty">Không tìm thấy tài khoản phù hợp.</span>}</div>
        </div>
          <button type="button" className="primary report-filter-apply" onClick={()=>setReportFilterOpen(false)}>Xem kết quả</button>
        </div>
        <div className="export-bar"><button className="primary" disabled={pending} onClick={()=>download('pdf')}><Download size={17}/> Xuất PDF tổng hợp</button><button className="secondary" disabled={pending} onClick={()=>download('zip')}><FileDown size={17}/> PDF riêng từng tài khoản (ZIP)</button></div>
      </section>
      <section className="surface report-results">
        <div className="section-title"><div><p className="eyebrow">Chi tiết đối soát</p><h2>Theo tài khoản nhận</h2></div><strong>{reports.data?money(reports.data.total):'—'}</strong></div>
        {reports.isLoading?<Spinner/>:reports.data?.groups.some(g=>g.count>0)?reports.data.groups.filter(g=>g.count>0).sort((a,b)=>b.total-a.total).map(g=><div className="report-group" key={g.account.name}><div className="report-account"><div><strong>{g.account.name}</strong><small>{g.account.bank||'Tài khoản lịch sử'}</small></div><div className="report-total"><strong>{money(g.total)}</strong><small>{g.count} giao dịch</small></div></div><div className="table-scroll mobile-card-table"><table className="transfer-report-table"><thead><tr><th>Ngày chuyển</th><th>Nhà / Phòng</th><th>Nội dung chuyển khoản</th><th>Số tiền</th></tr></thead><tbody>{g.receipts.map(r=><tr key={r.id}><td>{r.transferAt}</td><td><strong>{r.houseCode} · {r.room}</strong></td><td className="memo-cell">{r.transferMemo}</td><td className="emphasis">{money(r.amount)}</td></tr>)}</tbody></table></div></div>):<Blank message="Không có giao dịch phù hợp với bộ lọc"/>}
      </section>
      </>}
    </>}

    {tab==='assets'&&<Assets user={user} houses={meta.data?.houses||[]}/>}

    {tab==='admin'&&admin&&<><div className="subtabs">{([{key:'houses',label:'Tòa nhà',Icon:Building2},{key:'accounts',label:'Tài khoản nhận',Icon:CreditCard},{key:'users',label:'Nhân viên',Icon:Users},{key:'sync',label:'Đồng bộ Sheets',Icon:RefreshCw}] as const).map(n=><button key={n.key} className={adminTab===n.key?'active':''} onClick={()=>{setAdminTab(n.key);setAdminFormOpen(false)}}><n.Icon size={17}/>{n.label}</button>)}</div>
      {adminTab==='houses'&&<div className={'admin-grid '+(!adminFormOpen?'admin-grid-closed':'')}><section className="surface"><div className="section-title"><h2>Danh mục tòa nhà</h2><button className="secondary" onClick={()=>{setHouseForm({code:'',name:'',note:'',active:true});setAdminFormOpen(true)}}><Plus size={16}/> Thêm tòa nhà</button></div><div className="admin-search"><Search size={16}/><input aria-label="Tìm tòa nhà" placeholder="Tìm theo mã, tên hoặc ghi chú" value={adminHouseSearch} onChange={e=>setAdminHouseSearch(e.target.value)}/>{adminHouseSearch&&<button className="icon-btn" aria-label="Xóa tìm kiếm" onClick={()=>setAdminHouseSearch('')}><X size={16}/></button>}</div>{houses.isLoading?<Spinner/>:filteredAdminHouses.length?filteredAdminHouses.map(h=><button className="catalog-row" key={h.code} onClick={()=>{setHouseForm(h);setAdminFormOpen(true)}}><Building2 size={18}/><span><strong>{h.code} · {h.name}</strong><small>{h.note||'Không có ghi chú'}</small></span></button>):<Blank message={adminHouseSearch?'Không tìm thấy tòa nhà phù hợp':'Chưa có tòa nhà'}/>}</section>{adminFormOpen&&<section className="surface"><div className="section-title"><h2>{houses.data?.some(h=>h.code===houseForm.code)?'Cập nhật tòa nhà':'Thêm tòa nhà'}</h2><button className="icon-btn" aria-label="Đóng biểu mẫu" onClick={()=>setAdminFormOpen(false)}><X size={19}/></button></div><form onSubmit={saveHouse} className="form-stack"><label>Mã tòa nhà<input required disabled={houses.data?.some(h=>h.code===houseForm.code)} value={houseForm.code} onChange={e=>setHouseForm({...houseForm,code:e.target.value})}/></label><label>Tên hiển thị<input value={houseForm.name} onChange={e=>setHouseForm({...houseForm,name:e.target.value})}/></label><label>Ghi chú<textarea value={houseForm.note} onChange={e=>setHouseForm({...houseForm,note:e.target.value})}/></label><button className="primary" disabled={pending}>Lưu tòa nhà</button>{houses.data?.some(h=>h.code===houseForm.code)&&<button type="button" className="danger-btn" disabled={pending} onClick={()=>window.confirm('Xóa hoàn toàn tòa nhà này khỏi danh mục? Dữ liệu thu tiền lịch sử vẫn được giữ lại.')&&void deleteHouse()}><Trash2 size={16}/> Xóa tòa nhà</button>}<button type="button" className="link-btn" onClick={()=>setAdminFormOpen(false)}>Đóng</button></form></section>}</div>}
      {adminTab==='accounts'&&<div className={'admin-grid '+(!adminFormOpen?'admin-grid-closed':'')}><section className="surface"><div className="section-title"><h2>Danh mục tài khoản nhận</h2><button className="secondary" onClick={()=>{setAccountForm({name:'',bank:'',active:true});setAdminFormOpen(true)}}><Plus size={16}/> Thêm tài khoản</button></div>{accounts.isLoading?<Spinner/>:accounts.data?.length?accounts.data.map(a=><button className="catalog-row" key={a.name} onClick={()=>{setAccountForm(a);setAdminFormOpen(true)}}><CreditCard size={18}/><span><strong>{a.name}</strong><small>{a.bank||'Chưa cập nhật ngân hàng'}</small></span></button>):<Blank message="Chưa có tài khoản nhận"/>}</section>{adminFormOpen&&<section className="surface"><div className="section-title"><h2>{accounts.data?.some(a=>a.name===accountForm.name)?'Cập nhật tài khoản nhận':'Thêm tài khoản nhận'}</h2><button className="icon-btn" aria-label="Đóng biểu mẫu" onClick={()=>setAdminFormOpen(false)}><X size={19}/></button></div><form onSubmit={saveAccount} className="form-stack"><label>Tên tài khoản nhận<input required disabled={accounts.data?.some(a=>a.name===accountForm.name)} value={accountForm.name} onChange={e=>setAccountForm({...accountForm,name:e.target.value})}/></label><label>Ngân hàng<input required value={accountForm.bank} onChange={e=>setAccountForm({...accountForm,bank:e.target.value})}/></label><button className="primary" disabled={pending}>Lưu tài khoản</button>{accounts.data?.some(a=>a.name===accountForm.name)&&<button type="button" className="danger-btn" disabled={pending} onClick={()=>window.confirm('Xóa hoàn toàn tài khoản nhận này khỏi danh mục? Dữ liệu giao dịch cũ vẫn được giữ lại.')&&void deleteAccount()}><Trash2 size={16}/> Xóa tài khoản</button>}<button type="button" className="link-btn" onClick={()=>setAdminFormOpen(false)}>Đóng</button></form></section>}</div>}
      {adminTab==='users'&&<div className={'admin-grid '+(!adminFormOpen?'admin-grid-closed':'')}><section className="surface"><div className="section-title"><h2>Nhân viên và phân quyền</h2><button className="secondary" onClick={()=>{setStaffForm({id:'',login:'',name:'',password:'',role:'NV',active:true,houses:[],accounts:[]});setAdminFormOpen(true)}}><Plus size={16}/> Thêm nhân viên</button></div><div className="admin-search"><Search size={16}/><input aria-label="Tìm nhân viên" placeholder="Tìm tên, số điện thoại, vai trò hoặc tòa nhà" value={adminStaffSearch} onChange={e=>setAdminStaffSearch(e.target.value)}/>{adminStaffSearch&&<button className="icon-btn" aria-label="Xóa tìm kiếm" onClick={()=>setAdminStaffSearch('')}><X size={16}/></button>}</div>{staff.isLoading?<Spinner/>:filteredAdminStaff.length?filteredAdminStaff.map(u=><button className="catalog-row" key={u.id} onClick={()=>{setStaffForm({id:u.id,login:u.login,name:u.name,password:'',role:u.role,active:true,houses:u.houses,accounts:u.accounts});setAdminFormOpen(true)}}><Users size={18}/><span><strong>{u.name}</strong><small>{u.login} · {u.role==='ADMIN'?'Quản trị':u.role==='KETOAN'?'Kế toán':'Thu tiền'} · {u.hasPassword?'Đã có mật khẩu':'Cần cấp mật khẩu'}</small></span></button>):<Blank message={adminStaffSearch?'Không tìm thấy nhân viên phù hợp':'Chưa có nhân viên'}/>}</section>{adminFormOpen&&<section className="surface"><div className="section-title"><h2>{staffForm.id?'Cập nhật phân quyền':'Thêm nhân viên'}</h2><button className="icon-btn" aria-label="Đóng biểu mẫu" onClick={()=>setAdminFormOpen(false)}><X size={19}/></button></div><form className="form-stack" onSubmit={saveStaff}><label>Số điện thoại<input required disabled={!!staffForm.id} value={staffForm.login} onChange={e=>setStaffForm({...staffForm,login:e.target.value})}/></label><label>Họ tên<input required value={staffForm.name} onChange={e=>setStaffForm({...staffForm,name:e.target.value})}/></label><label>{staffForm.id?'Mật khẩu mới (để trống nếu giữ nguyên)':'Mật khẩu (ít nhất 10 ký tự)'}<input type="password" required={!staffForm.id} minLength={10} value={staffForm.password} onChange={e=>setStaffForm({...staffForm,password:e.target.value})}/></label><label>Vai trò<select value={staffForm.role} onChange={e=>setStaffForm({...staffForm,role:e.target.value as 'ADMIN'|'NV'|'KETOAN'})}><option value="NV">Nhân viên thu tiền</option><option value="KETOAN">Nhân viên kế toán</option><option value="ADMIN">Quản trị viên</option></select></label><div className="option-caption">Tòa nhà được phân quyền</div><div className="checkbox-row">{meta.data?.houses.map(h=><label className="check-pill" key={h.code}><input type="checkbox" checked={staffForm.houses.includes(h.code)} onChange={e=>setStaffForm({...staffForm,houses:e.target.checked?[...staffForm.houses,h.code]:staffForm.houses.filter(x=>x!==h.code)})}/>{h.code}</label>)}</div><div className="option-caption">Tài khoản nhận được phân quyền</div><div className="checkbox-row">{meta.data?.accounts.map(a=><label className="check-pill" key={a.name}><input type="checkbox" checked={staffForm.accounts.includes(a.name)} onChange={e=>setStaffForm({...staffForm,accounts:e.target.checked?[...staffForm.accounts,a.name]:staffForm.accounts.filter(x=>x!==a.name)})}/>{a.name}</label>)}</div><button className="primary" disabled={pending}>Lưu nhân viên</button>{staffForm.id&&<button type="button" className="danger-btn" disabled={pending} onClick={()=>window.confirm('Xóa nhân viên này khỏi quản trị? Toàn bộ lịch sử thu trước đây vẫn được giữ nguyên.')&&void deleteStaff()}><Trash2 size={16}/> Xóa nhân viên</button>}<button type="button" className="link-btn" onClick={()=>setAdminFormOpen(false)}>Đóng</button></form></section>}</div>}
      {adminTab==='sync'&&<><section className="surface"><div className="section-title"><h2>Tình trạng đồng bộ</h2><button className="secondary" disabled={pending} onClick={async()=>{await doAction(()=>post('/admin/sync/run',{}),'Đã chạy vòng kiểm tra đồng bộ');void qc.invalidateQueries({queryKey:['admin-sync']});}}><RefreshCw size={16}/> Đồng bộ ngay</button></div><p className="muted-text">Bảng tính đang liên kết: <strong>{sync.data?.binding||'—'}</strong>. Chỉ bật ghi thu sau khi dữ liệu đã được đối soát và cấu hình triển khai cho phép.</p><div className="sync-grid">{sync.data?.outbox.map(o=><div className="sync-tile" key={o.status}><Badge value={o.status}/><strong>{o._count}</strong><small>Giao dịch</small></div>)}{sync.data?.state.filter(s=>['lastPull','lastError','dueLastRead'].includes(s.key)).map(s=><div className="sync-tile" key={s.key}><small>{s.key==='lastPull'?'Đồng bộ lần cuối':s.key==='dueLastRead'?'Tải cần thu':'Lỗi gần nhất'}</small><strong className="sync-value">{s.value||'Không có'}</strong></div>)}</div></section><section className="surface"><div className="section-title"><h2>Xung đột cần xử lý</h2><span>{sync.data?.conflicts.length||0} trường hợp</span></div>{sync.isLoading?<Spinner/>:sync.data?.conflicts.length?sync.data.conflicts.map(c=><div className="conflict-row" key={c.id}><div><strong>{c.entityType} · {c.entityId}</strong><small>{c.reason}</small></div>{c.entityType==='receipt'&&<div className="inline-actions"><button disabled={pending} onClick={async()=>{await doAction(()=>post('/admin/sync/conflicts/'+c.id+'/resolve',{strategy:'sheet'}),'Đã chấp nhận dữ liệu Sheets');void qc.invalidateQueries({queryKey:['admin-sync']});}}>Dùng dữ liệu Sheets</button><button disabled={pending} onClick={async()=>{await doAction(()=>post('/admin/sync/conflicts/'+c.id+'/resolve',{strategy:'retry'}),'Đã đưa vào hàng đợi ghi lại');void qc.invalidateQueries({queryKey:['admin-sync']});}}>Ghi dữ liệu App</button></div>}</div>):<Blank message="Chưa có xung đột cần xử lý"/>}</section></>}
    </>}
    </main></div>
    <nav className="bottom-nav" aria-label="Điều hướng mobile">
      {nav.filter(n=>['dashboard','dues','collect','reports'].includes(n.id)).map(n=><button key={n.id} className={(tab===n.id?'active ':'')+(n.id==='collect'?'primary':'')} onClick={()=>navTo(n.id)}>{n.id==='collect'?<Plus size={21} strokeWidth={tab===n.id?2.2:1.8}/>:<n.Icon size={21} strokeWidth={tab===n.id?2.2:1.8}/>}<span>{n.title}</span></button>)}
      <button className={['history','assets','admin'].includes(tab)||mobileMoreOpen?'active':''} onClick={()=>setMobileMoreOpen(v=>!v)} aria-expanded={mobileMoreOpen} aria-controls="mobile-more-menu"><MoreHorizontal size={22}/><span>Thêm</span></button>
    </nav>

    {mobileMoreOpen&&<><button className="mobile-more-backdrop" aria-label="Đóng menu thêm" onClick={()=>setMobileMoreOpen(false)}/><section className="mobile-more-sheet" id="mobile-more-menu" role="dialog" aria-modal="true" aria-label="Thêm chức năng"><div className="mobile-more-grab"/><div className="mobile-more-head"><div><h2>Thêm chức năng</h2><p>Các mục quản lý và tra cứu ít dùng hơn</p></div><button className="icon-btn" aria-label="Đóng menu" onClick={()=>setMobileMoreOpen(false)}><X size={19}/></button></div><div className="mobile-more-list"><button onClick={()=>navTo('history')}><span className="mobile-more-icon"><History size={19}/></span><span><strong>Lịch sử</strong><small>Tra cứu và kiểm soát giao dịch</small></span><ChevronRight size={18}/></button><button onClick={()=>navTo('assets')}><span className="mobile-more-icon"><Boxes size={19}/></span><span><strong>Tài sản</strong><small>Kho, thiết bị, thuê và kiểm kê</small></span><ChevronRight size={18}/></button>{admin&&<button onClick={()=>navTo('admin')}><span className="mobile-more-icon"><Settings2 size={19}/></span><span><strong>Quản trị</strong><small>Nhân viên, tòa nhà, tài khoản nhận</small></span><ChevronRight size={18}/></button>}<button className="logout" onClick={logout}><span className="mobile-more-icon"><LogOut size={19}/></span><span><strong>Đăng xuất</strong><small>Kết thúc phiên làm việc</small></span><ChevronRight size={18}/></button></div></section></>}

    {pay&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){setPay(null);setConfirm(false)}}}><div className="modal" role="dialog" aria-modal="true" aria-label="Xác nhận thu tiền"><div className="modal-head"><div><p className="eyebrow">{editing?'Điều chỉnh giao dịch':'Ghi nhận thanh toán'}</p><h2>{pay.houseCode} · Phòng {pay.room}</h2><p>Kỳ thu {pay.month}</p></div><button aria-label="Đóng" className="icon-btn" onClick={()=>{setPay(null);setConfirm(false)}}><X size={20}/></button></div>{confirm?<div className="confirmation"><div className="confirmation-icon"><ShieldCheck size={29}/></div><h3>{editing?'Xác nhận lưu thay đổi':'Xác nhận thu tiền'}</h3><p>Kiểm tra thông tin trước khi ghi nhận vào hệ thống.</p><dl><dt>Tòa nhà / Phòng</dt><dd>{pay.houseCode} · {pay.room}</dd><dt>Kỳ thu</dt><dd>{pay.month}</dd><dt>Số tiền</dt><dd>{money(Number(pay.amount)||0)}</dd><dt>Hình thức</dt><dd>{pay.method}</dd>{pay.method==='Chuyển khoản'&&<><dt>Tài khoản nhận</dt><dd>{pay.accountName}</dd><dt>Ngày chuyển khoản</dt><dd>{toApiDate(pay.transferAt)}</dd><dt>Nội dung</dt><dd>{pay.transferMemo}</dd></>}</dl></div>:<div className="form-stack"><div className="field-pair"><label>Tháng thu<input value={pay.month} disabled/></label><label>Số tiền thực thu (đ)<input inputMode="numeric" type="number" min="1" required value={pay.amount} onChange={e=>setPay({...pay,amount:e.target.value})}/></label></div><label>Hình thức thanh toán<select value={pay.method} onChange={e=>setPay({...pay,method:e.target.value as PayForm['method']})}><option>Tiền mặt</option><option>Chuyển khoản</option></select></label>{pay.method==='Chuyển khoản'&&<><label>Tài khoản nhận<select value={pay.accountName} onChange={e=>setPay({...pay,accountName:e.target.value})}><option value="">Chọn tài khoản nhận</option>{meta.data?.accounts.filter(a=>a.active).map(a=><option key={a.name} value={a.name}>{a.name}</option>)}</select></label><label>Ngày chuyển khoản<input type="date" required value={pay.transferAt} onChange={e=>setPay({...pay,transferAt:e.target.value})}/></label><label>Nội dung chuyển khoản<input required value={pay.transferMemo} onChange={e=>setPay({...pay,transferMemo:e.target.value})} placeholder="Nội dung trên sao kê"/></label></>}<label>Ghi chú<textarea value={pay.note} onChange={e=>setPay({...pay,note:e.target.value})} placeholder="Ghi chú nội bộ (không bắt buộc)"/></label><label className="inline-check"><input type="checkbox" checked={allowDuplicate} onChange={e=>setAllowDuplicate(e.target.checked)}/> Tôi đã kiểm tra, cho phép giao dịch có thể trùng</label></div>}<div className="modal-actions"><button className="secondary" onClick={()=>confirm?setConfirm(false):setPay(null)}> {confirm?'Quay lại':'Hủy'} </button><button className="primary" disabled={pending||Number(pay.amount)<=0||(pay.method==='Chuyển khoản'&&(!pay.accountName||!pay.transferAt||!pay.transferMemo.trim()))} onClick={savePay}>{confirm?(editing?'Lưu sửa đổi':'Xác nhận thu'):'Tiếp tục'} <ArrowRight size={17}/></button></div></div></div>}
    {cancel&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setCancel(null)}}><div className="modal compact" role="dialog" aria-modal="true"><div className="modal-head"><h2>Hủy giao dịch?</h2><button className="icon-btn" onClick={()=>setCancel(null)}><X size={19}/></button></div><p>Giao dịch <strong>{cancel.id}</strong> · {cancel.houseCode}/{cancel.room} với số tiền <strong>{money(cancel.amount)}</strong> sẽ chuyển sang trạng thái đã hủy. Nhật ký thay đổi vẫn được lưu.</p><div className="modal-actions"><button className="secondary" onClick={()=>setCancel(null)}>Quay lại</button><button className="danger-btn" disabled={pending} onClick={removeReceipt}>Xác nhận hủy</button></div></div></div>}
  </div>;
}
function Pager({total,page,size,move}:{total:number;page:number;size:number;move:(p:number)=>void}){const max=Math.max(1,Math.ceil(total/size));return <div className="pager"><span>Trang {page}/{max} · {total} kết quả</span><div><button disabled={page===1} onClick={()=>move(page-1)} aria-label="Trang trước"><ChevronLeft size={18}/></button><button disabled={page>=max} onClick={()=>move(page+1)} aria-label="Trang sau"><ChevronRight size={18}/></button></div></div>}
const queryClient=new QueryClient({defaultOptions:{queries:{retry:1,refetchOnReconnect:true}}});
export default function Page(){return <QueryClientProvider client={queryClient}><Vincent/></QueryClientProvider>}
